		if (cnt>=M-10) for (;;);
	}
	void Add_Edge(int x,int y){
		Add(x,y);
		Add(y^1,x^1);
	}
	void Tarjan(int x){
		low[x]=dfn[x]=++id;
		stk[++*stk]=x;
		for (int i=las[x],y;~i;i=E[i].nxt)
			if (!dfn[y=E[i].y]){
				Tarjan(y);
				low[x]=min(low[x],low[y]);
			} else{
				if (!scc[y]) low[x]=min(low[x],dfn[y]);
			}
		if (low[x]==dfn[x]){
			int u;num++;
			do{
				u=stk[(*stk)--];
				seq[++*seq]=u;
				scc[u]=num;
			} while (u!=x);
		}
	}
	void Main(int __n){
		n=__n;
