void Link(int x,int y){
	E[cnt]=(Edge){y,las[x]};las[x]=cnt++;
	E[cnt]=(Edge){x,las[y]};las[y]=cnt++;
}
void dfs(int x){
	sz[x]=1;
	for (int i=las[x],y;~i;i=E[i].nxt)
		if ((y=E[i].y)!=fa[x]){
			fa[y]=x;
			dep[y]=dep[x]+1;
			dfs(y);
			sz[x]+=sz[y];
			if (sz[y]>sz[son[x]]) son[x]=y;
		}
}
void dfs(int x,int anc){
	id[x]=++tot;
	top[x]=anc;
	if (son[x]) dfs(son[x],anc);
	for (int i=las[x],y;~i;i=E[i].nxt){
		if ((y=E[i].y)!=fa[x]&&y!=son[x]) dfs(y,y);
	}
}

int pt1[N*4],pt2[N*4],vis[N*4];
int Ql,Qr,Qv,Time;

void Build(int x,int L,int R){
	pt1[x]=num,num+=2;
	pt2[x]=num,num+=2;
	if (L==R) return;
	Build(Lsn,L,Mid);
	Build(Rsn,Mid+1,R);
	TwoSAT::Add_Edge(pt1[x],pt1[Lsn]);
	TwoSAT::Add_Edge(pt1[x],pt1[Rsn]);
	TwoSAT::Add_Edge(pt2[x],pt2[Lsn]);
	TwoSAT::Add_Edge(pt2[x],pt2[Rsn]);
}
void Query1(int x,int L,int R){
	if (Ql<=L&&R<=Qr){
		TwoSAT::Add_Edge(Qv,pt1[x]);
		return;
	}
	if (Ql<=Mid) Query1(Lsn,L,Mid);
	if (Qr>Mid) Query1(Rsn,Mid+1,R);
}
void Query2(int x,int L,int R){
	if (Ql<=L&&R<=Qr){
		TwoSAT::Add_Edge(Qv,pt2[x]);
		return;
	}
	if (Ql<=Mid) Query2(Lsn,L,Mid);
	if (Qr>Mid) Query2(Rsn,Mid+1,R);
}
void Modify1(int x,int L,int R){
	if (vis[x]!=Time){
		vis[x]=Time;
		TwoSAT::Add_Edge(num,pt1[x]);
		pt1[x]=num,num+=2;
		if (num>=TwoSAT::N-10) for (;;);
		if (x>1){
			TwoSAT::Add_Edge(pt1[x/2],pt1[x]);
		}
	}
	if (Ql<=L&&R<=Qr){
		TwoSAT::Add_Edge(pt1[x],Qv);
		return;
	}
	if (Ql<=Mid) Modify1(Lsn,L,Mid);
	if (Qr>Mid) Modify1(Rsn,Mid+1,R);
}
void Modify2(int x,int L,int R){
	if (vis[x]!=Time){
		vis[x]=Time;
		TwoSAT::Add_Edge(num,pt2[x]);
