	if (Ql<=Mid) Modify2(Lsn,L,Mid);
	if (Qr>Mid) Modify2(Rsn,Mid+1,R);
}

void gao1(int i,int x,int y){
	int a=top[x],b=top[y];
	while (a!=b){
		if (dep[a]>dep[b]) swap(a,b),swap(x,y);
		Ql=id[b],Qr=id[y],Qv=i;
		Query1(1,1,n);
		y=fa[b],b=top[y];
