    string case_type = opt<string>("case_type", "possible");

    // Generate the tree according to tree_type.
    vector<pair<int, int>> edges; // Edges, will store pairs (u, v)

    if (tree_type == "chain") {
        for (int i = 2; i <= n; ++i) {
            edges.push_back({i - 1, i});
        }
    } else if (tree_type == "star") {
        for (int i = 2; i <= n; ++i) {
            edges.push_back({1, i});
        }
    } else if (tree_type == "balanced") {
        // Generate a balanced binary tree
        vector<int> nodes;
        for (int i = 1; i <= n; ++i) {
            nodes.push_back(i);
        }
        queue<int> q;
        q.push(nodes[0]);
        int idx = 1;
        while (idx < n) {
            int parent = q.front();
            q.pop();
            int leftChild = nodes[idx++];
            edges.push_back({parent, leftChild});
            q.push(leftChild);
            if (idx < n) {
                int rightChild = nodes[idx++];
                edges.push_back({parent, rightChild});
                q.push(rightChild);
            }
        }
    } else { // Random tree
        // Generate a random tree using Prüfer sequence
        vector<int> prufer;
        for (int i = 0; i < n - 2; ++i) {
            prufer.push_back(rnd.next(1, n));
