            degree[leaf]--;
            degree[v]--;
            if (degree[v] == 1) {
                leaves.insert(v);
            }
        }
        int u = *leaves.begin();
        int v = *leaves.rbegin();
        edges.push_back({u, v});
        // Optionally shuffle edges
        shuffle(edges.begin(), edges.end());
    }

    // Shuffle nodes to randomize labels
    vector<int> perm(n + 1);
    for (int i = 1; i <= n; ++i) {
        perm[i] = i;
    }
    shuffle(perm.begin() + 1, perm.end());
    for (auto& edge : edges) {
        edge.first = perm[edge.first];
        edge.second = perm[edge.second];
    }

