        // If m < requested m, fill the rest with random non-overlapping paths
        for (int i = m; i < opt<int>("m"); ++i) {
            int a = rnd.next(1, n);
            int b = rnd.next(1, n);
            while (a == b) b = rnd.next(1, n);
            int c = rnd.next(1, n);
            int d = rnd.next(1, n);
            while (c == d) d = rnd.next(1, n);
            ants.push_back(make_tuple(a, b, c, d));
        }

    } else if (case_type == "impossible") {
        // Generate ants such that the painting is impossible
        // Make all ants require the same path
        int u = perm[1];
        int v = perm[n];
        for (int i = 0; i < m; ++i) {
            // Both pairs are (u, v)
            ants.push_back(make_tuple(u, v, u, v));
        }
    } else if (case_type == "conflict") {
        // Generate ants with overlapping paths to create conflicts
        for (int i = 0; i < m; ++i) {
            int a = perm[1];
            int b = perm[rnd.next(2, n)];
            int c = perm[1];
            int d = perm[rnd.next(2, n)];
            ants.push_back(make_tuple(a, b, c, d));
        }
    } else {
        // Random ant pairs
        for (int i = 0; i < m; ++i) {
            int a = rnd.next(1, n);
            int b = rnd.next(1, n);
            while (a == b) b = rnd.next(1, n);
            int c = rnd.next(1, n);
