#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

const int MAXN = 100005;
const int MAXM = 10005;
const int MAXLOG = 17; // since 2^17 > 1e5

int n, m;
vector<int> adj[MAXN];
int parent[MAXN][MAXLOG]; // parent[node][k] = 2^k-th ancestor of node
int depth[MAXN];

void dfs(int u, int p) {
    parent[u][0] = p;
    if (p != -1)
        depth[u] = depth[p] + 1;
    else
        depth[u] = 0;
    for (int k = 1; k < MAXLOG; k++) {
        if (parent[u][k - 1] != -1)
            parent[u][k] = parent[parent[u][k - 1]][k - 1];
        else
            parent[u][k] = -1;
    }
    for (int v : adj[u]) {
        if (v != p) {
            dfs(v, u);
        }
    }
}

int getLCA(int u, int v) {
    if (depth[u] < depth[v])
        swap(u, v);
    // Lift u up so that depth[u] == depth[v]
    for (int k = MAXLOG - 1; k >= 0; k--) {
        if (parent[u][k] != -1 && depth[parent[u][k]] >= depth[v])
            u = parent[u][k];
    }
    if (u == v)
        return u;
    // Lift u and v up together
    for (int k = MAXLOG - 1; k >= 0; k--) {
        if (parent[u][k] != -1 && parent[u][k] != parent[v][k]) {
            u = parent[u][k];
            v = parent[v][k];
        }
    }
    return parent[u][0];
}

void addPathEdges(int u, int v, int lca, int antColor, map<pair<int, int>, int> &edgeColor, InStream& ouf) {
    // From u up to lca
    while (u != lca) {
        int p = parent[u][0];
        int a = min(u, p);
        int b = max(u, p);
        pair<int, int> edge = make_pair(a, b);
        if (edgeColor.find(edge) != edgeColor.end()) {
            if (edgeColor[edge] != antColor) {
                ouf.quitf(_wa, "Edge (%d, %d) is assigned to multiple ants", a, b);
            }
        } else {
            edgeColor[edge] = antColor;
        }
        u = p;
    }
    // From v up to lca
    while (v != lca) {
        int p = parent[v][0];
        int a = min(v, p);
        int b = max(v, p);
        pair<int, int> edge = make_pair(a, b);
        if (edgeColor.find(edge) != edgeColor.end()) {
            if (edgeColor[edge] != antColor) {
                ouf.quitf(_wa, "Edge (%d, %d) is assigned to multiple ants", a, b);
            }
        } else {
            edgeColor[edge] = antColor;
        }
        v = p;
    }
}

int main(int argc, char* argv[]) {
    registerTestlibCmd(argc, argv);

    n = inf.readInt(2, 100000);
    for (int i = 0; i < n - 1; i++) {
        int u = inf.readInt(1, n);
        int v = inf.readInt(1, n);
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    dfs(1, -1);

    m = inf.readInt(1, 10000);
    vector< pair<int, int> > antPair1(m), antPair2(m);
    for (int i = 0; i < m; i++) {
        int a_i = inf.readInt(1, n);
        int b_i = inf.readInt(1, n);
        int c_i = inf.readInt(1, n);
        int d_i = inf.readInt(1, n);
        if (a_i == b_i || c_i == d_i) {
            quitf(_fail, "Invalid favorite pairs in input");
        }
        antPair1[i] = make_pair(a_i, b_i);
        antPair2[i] = make_pair(c_i, d_i);
    }

    string juryAns = ans.readToken();
    if (juryAns != "YES" && juryAns != "NO") {
        quitf(_fail, "Invalid jury's answer");
    }

    string contAns = ouf.readToken();
    if (contAns != "YES" && contAns != "NO") {
        quitf(_pe, "Invalid participant's answer");
    }

    if (contAns == "NO") {
        if (juryAns == "NO") {
            quitf(_ok, "Correct answer: NO");
        } else if (juryAns == "YES") {
            quitf(_wa, "Participant outputs 'NO' but solution exists");
        } else {
            quitf(_fail, "Invalid jury's answer");
        }
    } else if (contAns == "YES") {
        if (juryAns == "NO") {
            quitf(_fail, "Participant found solution but jury says impossible");
        } else if (juryAns != "YES") {
            quitf(_fail, "Invalid jury's answer");
        }
        // Read participant's assignments
        vector<int> assignments(m);
        for (int i = 0; i < m; i++) {
            assignments[i] = ouf.readInt(1, 2, format("assignment[%d]", i + 1).c_str());
        }
        map<pair<int, int>, int> edgeColor; // edge -> ant color (1..m)
        for (int i = 0; i < m; i++) {
            int antColor = i + 1; // Each ant has unique color
            pair<int, int> assignedPair;
            if (assignments[i] == 1)
                assignedPair = antPair1[i];
            else if (assignments[i] == 2)
                assignedPair = antPair2[i];
            else
                ouf.quitf(_pe, "Invalid assignment for ant %d: %d", i + 1, assignments[i]);
            int u = assignedPair.first;
            int v = assignedPair.second;
            int lca = getLCA(u, v);
            addPathEdges(u, v, lca, antColor, edgeColor, ouf);
        }
        // If no conflicts, accept
        quitf(_ok, "Correct answer: YES");
    } else {
        quitf(_fail, "Invalid participant's answer");
    }
    return 0;
}

