using namespace std;
template <class T>
inline void read(T &x) {
  x = 0;
  register char c = getchar();
  register bool f = 0;
  while (!isdigit(c)) f ^= c == '-', c = getchar();
  while (isdigit(c)) x = x * 10 + c - '0', c = getchar();
  if (f) x = -x;
}
const int N = 2e5 + 10;
struct node {
  int x, y;
  inline node operator-(const node &rhs) const {
    return {x - rhs.x, y - rhs.y};
  }
  inline long long operator*(const node &rhs) const {
    return (long long)x * rhs.y - (long long)y * rhs.x;
  }
  inline bool operator<(const node &rhs) const {
    double tem = atan2(y, x) - atan2(rhs.y, rhs.x);
    return tem == 0 ? x < rhs.x : tem < 0;
  }
} a[N];
int n, m;
inline void quit() { puts("Ani"), exit(0); }
void solveSimple() {
  vector<int> x, y;
  for (int i = 1; i <= n; i++) {
    x.push_back(a[i].x);
    y.push_back(a[i].y);
  }
  auto make = [&](vector<int> &vec) {
    sort(vec.begin(), vec.end(), [](int a, int b) { return a > b; });
    vec.erase(unique(vec.begin(), vec.end()), vec.end());
    if (vec.size() && (vec[0] & 1)) quit();
    if (vec.size() > 1 && (vec[1] & 1)) quit();
  };
  make(x), make(y);
}
vector<int> convex(int l, int r) {
  vector<int> stk;
  auto top = [&]() { return a[stk.back()]; };
  auto nxt = [&]() { return a[stk[stk.size() - 2]]; };
  for (int i = l; i <= r; i++) {
    while (stk.size() > 1 && (top() - nxt()) * (a[i] - nxt()) <= 0)
      stk.pop_back();
    stk.push_back(i);
  }
  return stk;
}
int main() {
  read(n);
  for (int i = 1; i <= n; i++) read(a[i].x), read(a[i].y);
  solveSimple();
  sort(a + 1, a + n + 1);
  for (int i = 0; i <= n + 1; i++) a[i + n + 1] = a[i];
  vector<int> con = convex(0, n);
  for (int i : con)
    if ((a[i].x & 1) || (a[i].y & 1)) quit();
  for (int i = 0; i < con.size(); i++) {
    vector<int> cur =
