    if (type == "random") {
        // Generate random values between 0 and MAX_A
        for (int i = 0; i < n; ++i) {
            a[i] = rnd.next(0, MAX_A);
        }
    } else if (type == "zeros") {
        // All elements are zero
        for (int i = 0; i < n; ++i) {
            a[i] = 0;
        }
    } else if (type == "same") {
        // All elements are the same non-zero value
        int val = rnd.next(0, MAX_A);
        for (int i = 0; i < n; ++i) {
            a[i] = val;
        }
    } else if (type == "max") {
        // All elements are the maximum possible value
        for (int i = 0; i < n; ++i) {
            a[i] = MAX_A;
        }
    } else if (type == "sequence") {
        // Elements are sequential numbers starting from a random value
        int start = rnd.next(0, max(0, MAX_A - n));
        for (int i = 0; i < n; ++i) {
            a[i] = start + i;
        }
    } else if (type == "powers") {
        // Elements are powers of two
        int max_pow = 29; // Exponent up to 29
        for (int i = 0; i < n; ++i) {
            int exp = rnd.next(0, max_pow);
            a[i] = 1 << exp;
        }
    } else if (type == "highbits") {
        // Elements with high bits set, differing in the lower bits
        int high_bit = rnd.next(25, 29);
        for (int i = 0; i < n; ++i) {
            int suffix = rnd.next(0, (1 << high_bit) - 1);
            a[i] = (1 << high_bit) | suffix;
        }
    } else if (type == "near_max") {
        // Elements are near the maximum possible value
        for (int i = 0; i < n; ++i) {
            a[i] = MAX_A - rnd.next(0, 1000);
        }
    } else if (type == "small") {
        // Elements are small integers
        for (int i = 0; i < n; ++i) {
            a[i] = rnd.next(0, 1000);
        }
    } else if (type == "alternating") {
        // Elements alternate between two values
        int val1 = rnd.next(0, MAX_A);
        int val2 = rnd.next(0, MAX_A);
        for (int i = 0; i < n; ++i) {
            a[i] = (i % 2 == 0) ? val1 : val2;
        }
    } else if (type == "binary") {
        // Elements are 0 or 1
        for (int i = 0; i < n; ++i) {
            a[i] = rnd.next(0, 1);
        }
    } else {
        // Default to random if type is unrecognized
        for (int i = 0; i < n; ++i) {
            a[i] = rnd.next(0, MAX_A);
        }
    }

    // Output n
    printf("%d\n", n);
    // Output a_i
    for (int i = 0; i < n; ++i) {
        printf("%d%c", a[i], " \n"[i == n - 1]);
    }

    return 0;
