        vector<int> a(n);
        for (int i = 0; i < n; ++i) {
            a[i] = inf.readInt();
        }

        int even_count = 0;
        int odd_count = 0;
        for (int i = 0; i < n; ++i) {
            if (a[i] % 2 == 0)
                even_count++;
            else
                odd_count++;
        }
        bool has_solution;
        if (even_count >=1) {
            has_solution = true;
        }
        else if (odd_count >=2) {
            has_solution = true;
        }
        else {
            has_solution = false;
        }

        if (ouf.seekEof())
            quitf(_wa, "Unexpected EOF for test case %d", test);

        string first_line = ouf.readLine();
        stringstream first_line_stream(first_line);
        string first_token;
        if (!(first_line_stream >> first_token)) {
            quitf(_wa, "No output for test case %d", test);
        }

        if (first_token == "-1") {
            if (has_solution) {
                quitf(_wa, "Contestant reported no solution when one exists, on test case %d", test);
            }
            else {
                // Correct
                continue;
            }
        } else {
            if (!has_solution) {
                quitf(_wa, "Contestant reported a solution when none exists, on test case %d", test);
            }
            // Now parse k
            int k;
            {
                stringstream ss(first_token);
                if (!(ss >> k)) {
                    quitf(_wa, "Invalid k in test case %d", test);
                }
            }
            if (k < 1 || k > n) {
                quitf(_wa, "Invalid k=%d in test case %d", k, test);
            }
            // Now read the indices
            vector<int> indices;
            // First check whether there are more tokens in first_line_stream

            int idx;
            while (first_line_stream >> idx) {
                indices.push_back(idx);
            }
            while ((int)indices.size() < k) {
                if (ouf.seekEof())
                    quitf(_wa, "Not enough indices provided for test case %d", test);
                string indices_line = ouf.readLine();
                stringstream indices_stream(indices_line);
                while (indices_stream >> idx) {
                    indices.push_back(idx);
                }
            }
            if ((int)indices.size() != k) {
                quitf(_wa, "Number of indices read (%zu) does not match k (%d) for test case %d", indices.size(), k, test);
            }
            // Check indices are in range and distinct
            set<int> indices_set;
            for (int i = 0; i < k; ++i) {
                idx = indices[i];
                if (idx <1 || idx > n) {
                    quitf(_wa, "Index %d is out of range for test case %d", idx, test);
                }
                if (indices_set.count(idx)) {
                    quitf(_wa, "Duplicate index %d in indices for test case %d", idx, test);
                }
                indices_set.insert(idx);
            }
            // Check sum is even
            int sum = 0;
            for (int i = 0; i < k; ++i) {
                idx = indices[i];
                sum += a[idx -1]; // Convert to 0-based index
            }
            if (sum % 2 != 0) {
                quitf(_wa, "Sum of selected elements is odd (%d) in test case %d", sum, test);
            }
        }
    }
    // Make sure that there is no extra output after processing all test cases
    if (!ouf.seekEof()) {
        quitf(_wa, "Extra output after last test case");
    }
    quitf(_ok, "All test cases passed");
}

