        for (int i = 2; i <= n; ++i) {
            int u = rnd.next(1, i-1);
            edges.push_back({u, i});
        }
        shuffle(edges.begin(), edges.end());
    }
    return edges;
}

vector<int> generatePrimes(int m, string primeType) {
    // Generate m prime numbers between 2 and 6e4
    const int MAX_PRIME = 60000;
    static vector<int> primes;
    if (primes.empty()) {
        // Sieve of Eratosthenes
        vector<bool> is_prime(MAX_PRIME+1, true);
        for (int i = 2; i <= MAX_PRIME; ++i) {
            if (is_prime[i]) {
                primes.push_back(i);
                for (int j = i+i; j <= MAX_PRIME; j += i) {
                    is_prime[j] = false;
                }
            }
        }
    }
    vector<int> p_i;
    if (primeType == "small") {
        // Use small primes between 2 and 13 (e.g., first few primes)
        vector<int> small_primes {2, 3, 5, 7, 11, 13};
        for (int i = 0; i < m; ++i) {
            int idx = rnd.next(0, (int)small_primes.size()-1);
            p_i.push_back(small_primes[idx]);
        }
    } else if (primeType == "large") {
        // Use large primes from the primes list
        int start = upper_bound(primes.begin(), primes.end(), MAX_PRIME - 1000) - primes.begin();
        int sz = primes.size();
        for (int i = 0; i < m; ++i) {
            int idx = rnd.next(start, sz - 1);
            p_i.push_back(primes[idx]);
        }
    } else if (primeType == "same") {
        // Use the same prime repeatedly
        int idx = rnd.next(0, (int)primes.size() - 1);
        int p = primes[idx];
        for (int i = 0; i < m; ++i) {
            p_i.push_back(p);
        }
    } else if (primeType == "random") {
        for (int i = 0; i < m; ++i) {
            int idx = rnd.next(0, (int)primes.size() -1);
            p_i.push_back(primes[idx]);
        }
    } else {
        // Default to random
        for (int i = 0; i < m; ++i) {
            int idx = rnd.next(0, (int)primes.size() -1);
            p_i.push_back(primes[idx]);
        }
    }
    return p_i;
}

int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    int t = opt<int>("t", 1);  // number of test cases
    int n = opt<int>("n", 10); // number of nodes per test case
    int m = opt<int>("m", 10); // number of prime factors per test case
    string treeType = opt<string>("treeType", "random");
    string primeType = opt<string>("primeType", "random");

    // Ensure that total n and m don't exceed the maximum limits
    if ((long long)t * n > 100000) {
        fprintf(stderr, "Total n exceeds limit of 100000\n");
        exit(1);
    }
    if ((long long)t * m > 60000) {
        fprintf(stderr, "Total m exceeds limit of 60000\n");
        exit(1);
    }

    printf("%d\n", t); // Output t

    int total_n = 0;
    int total_m = 0;

    for (int tc = 0; tc < t; ++tc) {
        int cur_n = n;
        int cur_m = m;
        total_n += cur_n;
        total_m += cur_m;
        vector<pair<int,int>> edges = generateTree(cur_n, treeType);
        vector<int> primes_p_i = generatePrimes(cur_m, primeType);

        // Output the test case in the given format
        // n
        printf("%d\n", cur_n);
        // n-1 edges
        for (auto &e : edges) {
            printf("%d %d\n", e.first, e.second);
        }
        // m
        printf("%d\n", cur_m);
        // m primes
        for (int i = 0; i < cur_m; ++i) {
            printf("%d", primes_p_i[i]);
            if (i + 1 != cur_m) printf(" ");
        }
        printf("\n");
    }
    return 0;
