        // Count how many players want at least one win (type-2)
        int cntType2 = count(s.begin(), s.end(), '2');

        // Read the participant's verdict: either "YES" or "NO".
        // If they provide something else, we will fail (readToken would throw).
        string ansVerdict = ouf.readToken("YES|NO", "answerVerdict");

