        // The graph is connected and acyclic (since n-1 edges), hence it is a tree.

        // Preprocess for LCA
        int LOGN = 17;
        vector<vector<int>> up(n, vector<int>(LOGN));
        vector<int> depth(n);
        vector<int> tin(n), tout(n);
        int timer = 0;

        function<void(int, int)> dfs_lca = [&](int u, int p) {
            tin[u] = timer++;
            up[u][0] = p == -1 ? u : p;
            for (int i = 1; i < LOGN; ++i) {
                up[u][i] = up[up[u][i-1]][i-1];
