    int v, cap;
    double w;
    int rev;
    Edge() {}
    Edge(int t2, int t3, double t4, int t5) : v(t2), cap(t3), w(t4), rev(t5) {}
  };
  int V, s, t;
  vector<Edge> g[MAXV];
  void init(int n) {
    V = n + 2;
    s = n + 1;
    t = n + 2;
    for (int i = 1; i <= V; i++) {
      g[i].clear();
    }
  }
  void addEdge(int a, int b, int cap, double w) {
    g[a].emplace_back(b, cap, w, static_cast<int>(g[b].size()));
    g[b].emplace_back(a, 0, -w, static_cast<int>(g[a].size()) - 1);
  }
  double d[MAXV];
  int id[MAXV], mom[MAXV];
  bool inqu[MAXV];
  queue<int> qu;
  double solve() {
    int mxf = 0;
    double mnc = 0;
    while (1) {
      for (int i = 0; i <= V; i++) {
        d[i] = 1e9;
        inqu[i] = false;
        mom[i] = -1;
