        int u = qu.front();
        qu.pop();
        inqu[u] = 0;
        for (int i = 0; i < static_cast<int>(g[u].size()); i++) {
          Edge &e = g[u][i];
          int v = e.v;
          if (e.cap > 0 && d[v] > d[u] + e.w + eps) {
            d[v] = d[u] + e.w;
            mom[v] = u;
            id[v] = i;
            if (!inqu[v]) {
              qu.push(v);
              inqu[v] = 1;
            }
          }
        }
      }
      if (mom[t] == -1) {
        break;
      }
      int df = INF;
      for (int u = t; u != s; u = mom[u]) {
        df = min(df, g[mom[u]][id[u]].cap);
      }
      for (int u = t; u != s; u = mom[u]) {
        Edge &e = g[mom[u]][id[u]];
        e.cap -= df;
        g[e.v][e.rev].cap += df;
      }
      mxf += df;
      mnc += df * d[t];
