#include <bits/stdc++.h>
using namespace std;
const int INF = 1000000002;
const long long INFLL = 100000000000000000ll;
const long long MOD = 1000000007;
const int MAX = 200005;
bool Mark[MAX][2];
int Good[MAX][2];
int N, A[MAX];
long long D[MAX][2], End;
int dfs(int i, int step, long long sum) {
  End = max(End, sum);
  if (i < 1 || i > N) return 1;
  if (i == 1) {
    if (step == 0)
      return 0;
    else
      return 2;
  }
  if (Good[i][step]) {
    End = max(End, D[i][step] + sum);
    return Good[i][step];
  }
  if (Mark[i][step]) return Good[i][step] = 0;
  Mark[i][step] = true;
  if (step) {
    bool val = dfs(i - A[i], 1 - step, sum + A[i]);
    if (val) D[i][step] = End - sum;
    return Good[i][step] = val;
  } else {
    bool val = dfs(i + A[i], 1 - step, sum + A[i]);
    if (val) D[i][step] = End - sum;
    return Good[i][step] = val;
  }
}
int main() {
  cin >> N;
  for (int i = (2); i <= (N); i++) scanf("%d", &A[i]);
  for (int i = (1); i <= (N - 1); i++)
    if (!Mark[i + 1][1]) {
      End = 0;
      dfs(i + 1, 1, i);
    }
  for (int i = (1); i <= (N - 1); i++) {
    if (Good[i + 1][1] == 1)
      printf("%I64d\n", D[i + 1][1] + i);
    else if (Good[i + 1][1] == 2)
      printf("%I64d\n", D[i + 1][1] + i + i);
    else
      printf("-1\n");
  }
}

