        int maxEdges = n * (n - 1);
        if (m == -1) {
            if (type == "random_sparse") {
                m = rnd.next(n, min(maxEdges, n * 10)); // Sparse graph.
            } else {
                m = rnd.next(min(maxEdges, n * 10), maxEdges); // Dense graph.
            }
        } else {
            m = min(m, maxEdges);
        }
        while ((int)edges.size() < m) {
            int a = rnd.next(1, n);
            int b = rnd.next(1, n);
            if (a != b && edgeSet.find({a, b}) == edgeSet.end()) {
                edges.push_back({a, b});
                edgeSet.insert({a, b});
            }
        }
    } else if (type == "maximal_rhombi") {
        // Generate a graph designed to maximize the number of rhombi.
        // Create layers and connect every node in a layer to every node in the next layer.
        if (layers < 2 || layers > n) layers = 2;
        vector<vector<int>> layerNodes(layers);
        int idx = 1;
        for(int l = 0; l < layers; ++l) {
            int layerSize = n / layers + (l < n % layers);
            for(int i = 0; i < layerSize; ++i) {
                layerNodes[l].push_back(idx++);
            }
        }
        for(int l = 0; l < layers - 1; ++l) {
            for(int u : layerNodes[l]) {
                for(int v : layerNodes[l + 1]) {
                    edges.push_back({u, v});
                    edgeSet.insert({u, v});
                }
            }
        }
        m = edges.size();
    } else if (type == "minimal_rhombi") {
        // Generate a graph designed to minimize the number of rhombi.
        // Use a chain graph (no rhombi).
        m = n - 1;
        for(int i = 1; i < n; ++i) {
            edges.push_back({i, i + 1});
            edgeSet.insert({i, i + 1});
        }
    } else {
        // Default to random_sparse if unknown type.
        type = "random_sparse";
        int maxEdges = n * (n - 1);
        if (m == -1) {
            m = rnd.next(n, min(maxEdges, n * 10));
        } else {
            m = min(m, maxEdges);
        }
        while ((int)edges.size() < m) {
            int a = rnd.next(1, n);
            int b = rnd.next(1, n);
            if (a != b && edgeSet.find({a, b}) == edgeSet.end()) {
                edges.push_back({a, b});
                edgeSet.insert({a, b});
            }
        }
    }

    // Output the graph.
    printf("%d %d\n", n, m);
    for(auto e : edges) {
        printf("%d %d\n", e.first, e.second);
    }

    return 0;
}

