        }
        // Read digits
        size_t start = pos;
        while (pos < line.size() && isdigit(line[pos])) {
            pos++;
        }
        if (start == pos) {
            quitf(_fail, "Expected a number at position %d", (int)pos);
        }
        tokens.push_back(line.substr(start, pos - start));
        if ((int)tokens.size() > n) {
            quitf(_fail, "More numbers than expected");
        }
        // After number, expect either space or end of line
        if (pos < line.size()) {
            if (line[pos] != ' ') {
                quitf(_fail, "Expected a single space or end of line at position %d", (int)pos);
            }
            pos++; // Skip the space
            if (pos < line.size() && line[pos] == ' ') {
                quitf(_fail, "Multiple spaces detected at position %d", (int)pos);
            }
        }
    }

    if ((int)tokens.size() != n) {
        quitf(_fail, "Expected %d numbers, found %d", n, (int)tokens.size());
    }

    for (int i = 0; i < n; ++i) {
        string num_str = tokens[i];
        if (num_str.empty()) {
            quitf(_fail, "Empty token at position %d", i+1);
