        if (num_str[0] == '0') {
            quitf(_fail, "Leading zero in number at position %d", i+1);
        }
        int num = atoi(num_str.c_str());
        if (num < 1 || num > 100000) {
            quitf(_fail, "Number out of range at position %d", i+1);
        }
    }

    inf.readEof();

    return 0;
}

