                    ny += dy[dir];
                }
            }
        }
    } else if (type == "random_yes") {
        // Random 'YES' case
        int num_shifts = rnd.next(1, n);
        set<pair<int,int>> shifts;
        while (shifts.size() < num_shifts) {
            int dx = rnd.next(-n+1, n-1);
            int dy = rnd.next(-n+1, n-1);
            if (dx == 0 && dy == 0) continue;
            shifts.insert({dx, dy});
        }

        int num_pieces = rnd.next(1, n);
        vector<pair<int, int>> pieces;
        for (int k = 0; k < num_pieces; ++k) {
            int x, y;
            do {
                x = rnd.next(0, n-1);
                y = rnd.next(0, n-1);
            } while (board[x][y] == 'o');
            board[x][y] = 'o';
            pieces.push_back({x, y});
        }

        for (auto [x, y] : pieces) {
            for (auto [dx, dy] : shifts) {
                int nx = x + dx;
                int ny = y + dy;
                if (nx >= 0 && nx < n && ny >= 0 && ny < n && board[nx][ny] != 'o') {
                    if (board[nx][ny] == '.') {
                        board[nx][ny] = 'x';
                    }
                }
            }
        }
    } else if (type == "random_no") {
        // Random 'NO' case
        if (n < 2) n = 2;
        board.resize(n, string(n, '.'));
        int cx = n / 2;
        int cy = n / 2;
        board[cx][cy] = 'o';

        board[0][0] = 'x';
        board[0][n - 1] = 'x';
        board[n - 1][0] = 'x';
        board[n - 1][n - 1] = 'x';
    } else if (type == "minimal_yes") {
        n = (n >= 1 && n <= 2) ? n : 1;
        board.resize(n, string(n, '.'));
        board[0][0] = 'o';
    } else if (type == "minimal_no") {
        n = (n >= 1 && n <= 2) ? n : 1;
        board.resize(n, string(n, '.'));
        board[0][0] = 'o';
        if (n > 1) {
            board[0][1] = 'x';
            board[1][1] = 'x';
        }
    } else if (type == "edge_yes") {
        n = 50;
        board.resize(n, string(n, '.'));
        int cx = n / 2;
        int cy = n / 2;
        board[cx][cy] = 'o';

        int dx[] = {1,-1,0,0,1,1,-1,-1};
        int dy[] = {0,0,1,-1,1,-1,1,-1};
        for (int dir = 0; dir < 8; ++dir) {
            int nx = cx + dx[dir];
            int ny = cy + dy[dir];
            while (nx >= 0 && nx < n && ny >= 0 && ny < n) {
                if (board[nx][ny] == '.') {
                    board[nx][ny] = 'x';
                }
                nx += dx[dir];
                ny += dy[dir];
            }
        }
    } else if (type == "edge_no") {
        n = 50;
        board.resize(n, string(n, '.'));
        board[0][0] = 'o';
        board[0][1] = 'o';
        board[n-1][n-1] = 'x';
    } else {
        n = rnd.next(1, 50);
        board.resize(n, string(n, '.'));
        int num_pieces = rnd.next(1, n);
        for (int k = 0; k < num_pieces; ++k) {
            int x, y;
            x = rnd.next(0, n-1);
            y = rnd.next(0, n-1);
            board[x][y] = 'o';
        }
    }

    // Output the board
    printf("%d\n", n);
    for (int i = 0; i < n; ++i) {
        printf("%s\n", board[i].c_str());
    }

    return 0;
}

