        } else {
            quitf(_ok, "Correct answer: NO");
        }
    } else {
        // ans_opt == "YES"
        if (con_opt != "YES") {
            quitf(_wa, "Participant's answer is 'NO', but the correct answer is 'YES'");
        }

        int m = 2 * n - 1;
        vector<string> shift_pattern(m);
        for (int i = 0; i < m; ++i) {
            shift_pattern[i] = ouf.readToken(format("[x.o]{%d}", m).c_str(), format("shift pattern line #%d", i+1).c_str());
            if ((int)shift_pattern[i].length() != m) {
                quitf(_pe, "Length of shift pattern line #%d should be %d, but found %d", i+1, m, (int)shift_pattern[i].length());
            }
        }

        if (shift_pattern[n - 1][n - 1] != 'o') {
            quitf(_wa, "Center of shift pattern at position (%d, %d) should be 'o'", n, n);
        }

        set<pair<int, int>> shifts;
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < m; ++j) {
                if (i == n - 1 && j == n - 1) continue; // Skip center
                char ch = shift_pattern[i][j];
                if (ch == 'x') {
                    int dx = j - (n - 1);
                    int dy = i - (n - 1);
                    shifts.insert(make_pair(dx, dy));
                } else if (ch != '.') {
                    quitf(_wa, "Invalid character '%c' in shift pattern at position (%d, %d)", ch, i + 1, j + 1);
                }
            }
        }

        int N = n;
        vector<vector<bool>> attacked(N, vector<bool>(N, false));

        for (int y = 0; y < N; ++y) {
            for (int x = 0; x < N; ++x) {
                if (board[y][x] == 'o') {
                    for (auto shift : shifts) {
                        int dx = shift.first;
                        int dy = shift.second;
                        int nx = x + dx;
                        int ny = y + dy;
                        if (0 <= nx && nx < N && 0 <= ny && ny < N) {
                            if (board[ny][nx] != 'o') {
                                attacked[ny][nx] = true;
                            }
                        }
                    }
                }
            }
        }

        for (int y = 0; y < N; ++y) {
            for (int x = 0; x < N; ++x) {
                if (board[y][x] == 'x') {
                    if (!attacked[y][x]) {
                        quitf(_wa, "Cell (%d, %d) should be attacked, but it is not", y + 1, x + 1);
                    }
                } else if (board[y][x] == '.') {
                    if (attacked[y][x]) {
                        quitf(_wa, "Cell (%d, %d) should not be attacked, but it is", y + 1, x + 1);
                    }
                }
                // We don't care about 'o' cells
            }
        }

        quitf(_ok, "Correct answer: YES");
    }
}

