#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

/*
  This generator produces a single test case for the problem:
    - n cities, numbered 1..n
    - m roads (bidirectional)
    - a_i soldiers initially in city i
    - b_i soldiers required finally in city i
    - 1 <= n <= 100
    - 0 <= m <= 200
    - 0 <= a_i, b_i <= 100
    - at most one road between a pair of cities (no duplicates)

  Command-line parameters:
    -n <int> : number of cities
    -m <int> : number of roads (optional; if not provided, we choose automatically)
    -type <string> : type of test. Possible values:
        1) "random"      : random a[], b[], random edges
        2) "complete"    : produce a fully-connected graph if possible,
                           or as many edges as allowed (200)
        3) "disconnected": produce at least two components
        4) "all-zero"    : all a_i = 0, all b_i = 0, edges random
        5) "star"        : produce a star-like structure for edges
*/

int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    // Parsing arguments
    int n = opt<int>("n");                      // required
    int m_provided = opt<int>("m", -1);         // optional
    string type = opt<string>("type", "random");

    // Ensure constraints on n
    // The statement says 1 <= n <= 100, but we trust the user
    // to not pass invalid values. Same for m.

    // Decide how many edges to generate if not provided
    // The upper bound for edges is min(n*(n-1)/2, 200).
    int maxPossibleEdges = n * (n - 1) / 2;
    if (maxPossibleEdges > 200) {
        maxPossibleEdges = 200;
    }

    int m;
    if (m_provided == -1) {
        // We'll pick a random number of edges from [0, maxPossibleEdges]
        m = rnd.next(maxPossibleEdges + 1);
    } else {
        // Use the provided parameter, but clamp to feasible range
        m = min(m_provided, maxPossibleEdges);
        if (m < 0) m = 0;
    }

    // Prepare arrays a and b
    vector<int> a(n), b(n);

    // We'll define how to generate a[] and b[] based on type
    if (type == "all-zero") {
        // All are zero
        for (int i = 0; i < n; i++) {
            a[i] = 0;
            b[i] = 0;
        }
    } else {
        // By default, generate random a[i], b[i] in [0..100]
        // (Except for "disconnected", "complete", or "star", we might
        //  still do random, or do something specialized. 
        //  But we'll keep it simple and produce random in these as well,
        //  except for "all-zero".)
        for (int i = 0; i < n; i++) {
            a[i] = rnd.next(0, 100);
            b[i] = rnd.next(0, 100);
        }
    }

    // Generate edges
    // We'll create a candidate list of all possible edges (i < j), then choose
    // the needed number based on the test type.
    // For "complete": we take as many distinct edges as possible (up to 200).
    // For "disconnected": we will partition into two subgraphs so that there's no cross-edge.
    // For "star": 1 center with edges to all other nodes.
    // For "random": just pick any random subset of edges of size m.

    vector<pair<int,int>> allEdges;
    allEdges.reserve(maxPossibleEdges);

    // Helper lambda to add edges (i, j), i < j
    auto addAllPossibleEdges = [&](int start, int end) {
        // add pairs in [start, end) so that i<j
        for (int i = start; i < end; i++) {
            for (int j = i + 1; j < end; j++) {
                allEdges.push_back({i, j});
            }
        }
    };

    if (type == "complete") {
        // Try to make a complete graph if feasible
        // i.e., edges = min(n*(n-1)/2, 200)
        allEdges.clear();
        addAllPossibleEdges(0, n);
        m = min(m, (int)allEdges.size());
        // no shuffle needed if we literally want them all,
        // but let's shuffle to avoid sorted output
        shuffle(allEdges.begin(), allEdges.end());
        allEdges.resize(m);
    } 
    else if (type == "disconnected" && n > 1) {
        // We'll force a partition into 2 disjoint sets
        // We choose a random k in [1, n-1]
        int k = rnd.next(1, n-1);
        // subgraph1: nodes [0..k-1]
        // subgraph2: nodes [k..n-1]
        // We'll generate random edges inside each subgraph, but no cross edges.
        allEdges.clear();
        addAllPossibleEdges(0, k);
        addAllPossibleEdges(k, n);
        // Shuffle them
        shuffle(allEdges.begin(), allEdges.end());
        // Possibly create fewer edges than the total inside these subgraphs
        m = min(m, (int)allEdges.size());
        allEdges.resize(m);
    }
    else if (type == "star" && n > 1) {
        // We'll produce a star from node 0 to all others
        // That yields exactly n-1 edges if n>1 (unless n=1, we skip)
        // If user wants more edges, we won't add them. 
        // If user wants fewer, we'll clamp. But typically star is just (n-1) edges.
        allEdges.clear();
        for (int i = 1; i < n; i++) {
            allEdges.push_back({0, i});
        }
        // Number of edges is n-1 or maybe fewer if user-specified m < n-1
        m = min(m, n-1);
        // If user wants to omit some edges from the star, we can shuffle and trim
        shuffle(allEdges.begin(), allEdges.end());
        allEdges.resize(m);
    }
    else {
        // "random" or fallback
        // We'll pick a random subset of all possible edges
        // up to size m
        allEdges.clear();
        addAllPossibleEdges(0, n);
        shuffle(allEdges.begin(), allEdges.end());
        m = min(m, (int)allEdges.size());
        allEdges.resize(m);
    }

    // Now we have a[] and b[], plus m edges in allEdges
    // Let's output in the required format.

    // 1) print n and m
    cout << n << " " << m << "\n";

    // 2) print a1..an
    for (int i = 0; i < n; i++) {
        cout << a[i];
        if (i + 1 < n) cout << " ";
    }
    cout << "\n";

    // 3) print b1..bn
    for (int i = 0; i < n; i++) {
        cout << b[i];
        if (i + 1 < n) cout << " ";
    }
    cout << "\n";

    // 4) print edges
    //     each edge is (p, q), with p != q and 1 <= p,q <= n
    //     here we stored them as 0-based, so convert to 1-based
    for (auto &e : allEdges) {
        cout << e.first + 1 << " " << e.second + 1 << "\n";
    }

    return 0;
}

