using namespace std;

const int MAX_N = 105;

int n, m;
int ai[MAX_N], bi[MAX_N];
set<int> adj[MAX_N];
int M[MAX_N][MAX_N];

int main(int argc, char* argv[]) {
    registerTestlibCmd(argc, argv);

    // Read input data
    n = inf.readInt(1, 100, "n");
    m = inf.readInt(0, 200, "m");

    for (int i = 1; i <= n; ++i) {
        ai[i] = inf.readInt(0, 100, format("ai[%d]", i).c_str());
    }

    for (int i = 1; i <= n; ++i) {
        bi[i] = inf.readInt(0, 100, format("bi[%d]", i).c_str());
    }

    for (int i = 0; i < m; ++i) {
        int u = inf.readInt(1, n, format("edge %d u", i+1).c_str());
        int v = inf.readInt(1, n, format("edge %d v", i+1).c_str());
        if (u == v) {
            inf.quitf(_fail, "Self loop detected in input: edge between %d and %d", u, v);
        }
        adj[u].insert(v);
        adj[v].insert(u);
    }

    // Read jury's answer
    string juryAns = ans.readToken();
    if (juryAns != "YES" && juryAns != "NO") {
        quitf(_fail, "Jury's answer must be YES or NO, found '%s'", juryAns.c_str());
    }

    // Read participant's answer
    string partAns = ouf.readToken();
    if (partAns != "YES" && partAns != "NO") {
        quitf(_pe, "Your answer must be YES or NO, found '%s'", partAns.c_str());
    }

    if (partAns == "NO") {
        if (juryAns == "NO") {
            ouf.skipBlanks();
            if (!ouf.eof())
                quitf(_pe, "Extra information after NO");
            quitf(_ok, "Correctly answered NO");
        } else {
            quitf(_wa, "Participant answered NO, but solution exists");
        }
    } else if (partAns == "YES") {
        // Participant answered YES
        // Read the n x n matrix
        memset(M, 0, sizeof(M));

        for (int i = 1; i <= n; ++i) {
            // Read n integers
            for (int j = 1; j <= n; ++j) {
                if (ouf.seekEof())
                    quitf(_pe, "Too few numbers in row %d", i);
                M[i][j] = ouf.readInt(0, 10000, format("M[%d][%d]", i, j).c_str());
            }
        }

        // Check for extra output
        ouf.skipBlanks();
        if (!ouf.eof()) {
            quitf(_pe, "Extra information after reading matrix");
        }

        // Validate the matrix
        // 1. All M[i][j] >= 0
        // Already ensured during reading

        // 2. For each i, sum over j of M[i][j] == ai[i]
        for (int i = 1; i <= n; ++i) {
            int sum_out = 0;
            for (int j = 1; j <= n; ++j) {
                sum_out += M[i][j];
            }
