vector<int> generate_k_distinct_numbers(int k, int n) {
    vector<int> xi;
    if (k <= n / 2) {
        set<int> xi_set;
        while ((int)xi_set.size() < k) {
            int val = rnd.next(1, n);
            xi_set.insert(val);
        }
        xi.assign(xi_set.begin(), xi_set.end());
    } else {
        vector<int> perm(n);
        for (int i = 0; i < n; ++i) {
            perm[i] = i + 1;
        }
        shuffle(perm.begin(), perm.end());
        xi.assign(perm.begin(), perm.begin() + k);
    }
    sort(xi.begin(), xi.end());
    return xi;
}

int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    int n = opt<int>("n");
    int k = opt<int>("k");
    int l = opt<int>("l");
    string type = opt<string>("type", "random");

    if (n < 1 || n > 10000) {
        fprintf(stderr, "Invalid n\n");
        return 1;
    }
    if (k < 1 || k > 10) {
        fprintf(stderr, "Invalid k\n");
        return 1;
    }
    if (l < 1 || l > 100) {
        fprintf(stderr, "Invalid l\n");
        return 1;
    }

    vector<int> xi;
    vector<int> ai(l);

    if (type == "random") {
        xi = generate_k_distinct_numbers(k, n);

        for (int i = 0; i < l; ++i) {
            ai[i] = rnd.next(1, n);
        }

    } else if (type == "impossible") {
        if (n % 2 == 0) n += 1;
        if (n > 10000) n = 10000;
        k = 1;
        xi = { (n + 1) / 2 };

        for (int i = 0; i < l; ++i) {
            ai[i] = rnd.next(2, n / 2) * 2;
            if (ai[i] > n) ai[i] = n;
        }

    } else if (type == "max_l") {
        l = 100;
        ai.resize(l);
        for (int i = 0; i < l; ++i) {
            ai[i] = rnd.next(1, n);
        }
        k = rnd.next(1, min(10, n));
        xi = generate_k_distinct_numbers(k, n);

    } else if (type == "min_l") {
        l = 1;
        ai = { rnd.next(1, n) };
        k = rnd.next(1, min(10, n));
        xi = generate_k_distinct_numbers(k, n);

    } else if (type == "maximal_moves") {
        k = rnd.next(1, 10);
        xi = vector<int>(k);
        int step = max(1, n / k);
        for (int i = 0; i < k; ++i) {
            xi[i] = min(1 + i * step, n);
        }
        sort(xi.begin(), xi.end());

        for (int i = 0; i < l; ++i) {
            ai[i] = rnd.next(1, 2);
        }

    } else if (type == "small_flips") {
        for (int i = 0; i < l; ++i) {
            ai[i] = rnd.next(1, 3);
        }
        k = rnd.next(1, 10);
        xi = generate_k_distinct_numbers(k, n);

    } else if (type == "large_flips") {
        for (int i = 0; i < l; ++i) {
            ai[i] = rnd.next(max(1, n - 20), n);
        }
        k = rnd.next(1, 10);
        xi = generate_k_distinct_numbers(k, n);

    } else if (type == "same_flips") {
        int flip_size = rnd.next(1, n);
        for (int i = 0; i < l; ++i) {
            ai[i] = flip_size;
        }
        k = rnd.next(1, 10);
        xi = generate_k_distinct_numbers(k, n);

    } else if (type == "minimal") {
        xi = generate_k_distinct_numbers(k, n);
        for (int i = 0; i < l; ++i) {
            ai[i] = rnd.next(1, n);
        }
    } else {
