    // Print the first line: n, a, b
    cout << n << " " << a << " " << b << "\n";

    // We will store the group sizes in this vector.
    vector<int> groups(n, 1);

    if (type == "random") {
        // Each group is either 1 or 2 with roughly equal probability
        for (int i = 0; i < n; ++i) {
            groups[i] = rnd.next(1, 2);
        }
    } 
    else if (type == "allones") {
        // Make all groups have size 1
        // (vector is already initialized with 1, so nothing needed)
    }
    else if (type == "alltwos") {
        // Make all groups have size 2
        for (int i = 0; i < n; ++i) {
            groups[i] = 2;
        }
    }
    else if (type == "mixedheavyones") {
        // Let 75% be 1, 25% be 2
        for (int i = 0; i < n; ++i) {
            // next(4) gives 0..3
            // if <3 => 1, else => 2
            groups[i] = (rnd.next(4) < 3) ? 1 : 2;
        }
    }
    else if (type == "mixedheavytwos") {
        // Let 75% be 2, 25% be 1
        for (int i = 0; i < n; ++i) {
            groups[i] = (rnd.next(4) < 1) ? 1 : 2;
        }
    }
    else if (type == "alternating") {
        // 1, 2, 1, 2, ...
        for (int i = 0; i < n; ++i) {
            groups[i] = (i % 2 == 0) ? 1 : 2;
        }
    }
    else if (type == "halfsplit") {
        // First half 1, second half 2
        for (int i = 0; i < n; ++i) {
            if (i < n/2) groups[i] = 1;
            else groups[i] = 2;
        }
    }
    else if (type == "smallblock") {
        // Slide small blocks of 1's and 2's: e.g. (1,1,2), (1,2,2), ...
        // We'll choose a random block length in [1..3], fill with random 1 or 2
        // then repeat until we fill n
        int i = 0;
        while (i < n) {
            int blockLen = rnd.next(1, 3);
            int val = rnd.next(1, 2);
            for (int j = 0; j < blockLen && i < n; ++j, ++i) {
                groups[i] = val;
            }
        }
    }
    else {
        // Fallback: treat as "random"
        for (int i = 0; i < n; ++i) {
            groups[i] = rnd.next(1, 2);
        }
    }

    // Print group sizes
    for (int i = 0; i < n; ++i) {
        cout << groups[i];
        if (i + 1 < n) cout << " ";
    }
    cout << "\n";

    return 0;
}

