import java.util.HashMap;
import java.util.PriorityQueue;
import java.util.Scanner;

public class D864Permutation {

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int n = in.nextInt();
		HashMap<Integer, Integer> hm = new HashMap<>();
		boolean[] vis = new boolean[n + 1];
		int[] ar = new int[n];
		for (int i = 0; i < n; i++) {
			int t = in.nextInt();
			ar[i] = t;
			hm.put(t, hm.getOrDefault(t, 0) + 1);
 		}
		PriorityQueue<Integer> pq = new PriorityQueue<Integer>();
		for (int i = 1; i <= n; i++) {
			if (!hm.containsKey(i)) {
				pq.add(i);
			}
		}
		int ans = 0;
		for (int i = 0; i < n; i++) {
			if (hm.getOrDefault(ar[i], 1) == 1) {
				continue;
			} else {
				if (vis[ar[i]] || ar[i] > pq.peek()) {
					ar[i] = pq.poll();
					ans++;
				} else {
					vis[ar[i]] = true;
				}
			}
			if (pq.size() == 0) {
				break;
			}
		}
		System.out.println(ans);
		for (int e : ar) {
			System.out.print(e + " ");
		}
		System.out.println();

	}

}

