        for (int i = 0; i < n; ++i) {
            a[i] = rnd.next(1, n);
        }
    } else if (type == "permutation") {
        for (int i = 0; i < n; ++i) {
            a[i] = i + 1;
        }
        shuffle(a.begin(), a.end());
    } else if (type == "all_same") {
        int num = rnd.next(1, n);
        for (int i = 0; i < n; ++i) {
            a[i] = num;
        }
    } else if (type == "few_duplicates") {
        // Start with a permutation
        for (int i = 0; i < n; ++i) {
            a[i] = i + 1;
        }
        shuffle(a.begin(), a.end());
        // Introduce some duplicates
        int num_changes = n / 10 + 1; // change about 10% of the elements
        for (int i = 0; i < num_changes; ++i) {
            int pos = rnd.next(0, n - 1);
            a[pos] = rnd.next(1, n);
        }
    } else if (type == "missing_numbers") {
        // Remove some numbers and duplicate others
        set<int> numbers;
        for (int i = 1; i <= n; ++i) {
            numbers.insert(i);
        }
        int num_missing = n / 10 + 1; // Remove about 10% of numbers
        vector<int> missing_nums;
        for (int i = 0; i < num_missing; ++i) {
            int num = rnd.next(1, n);
            if (numbers.count(num)) {
                numbers.erase(num);
                missing_nums.push_back(num);
            }
        }
        vector<int> remaining_numbers(numbers.begin(), numbers.end());
        for (int i = 0; i < n; ++i) {
            a[i] = remaining_numbers[rnd.next(0, (int)remaining_numbers.size() - 1)];
        }
    } else if (type == "reverse") {
        for (int i = 0; i < n; ++i) {
            a[i] = n - i;
        }
    } else if (type == "maximal_duplicates") {
        int num = rnd.next(1, n);
        for (int i = 0; i < n; ++i) {
            a[i] = num;
        }
    } else if (type == "single_duplicate") {
        // Create a permutation
        for (int i = 0; i < n; ++i) {
            a[i] = i + 1;
        }
        // Introduce a single duplicate
        int dup_pos = rnd.next(0, n - 1);
        int rem_pos;
        do {
            rem_pos = rnd.next(0, n - 1);
        } while (rem_pos == dup_pos);
        a[dup_pos] = a[rem_pos];
    } else if (type == "single_missing") {
        // Start with a shuffled permutation
        vector<int> perm(n);
        for (int i = 0; i < n; ++i) {
            perm[i] = i + 1;
        }
        shuffle(perm.begin(), perm.end());
        // Replace one number with a duplicate
        int missing_num = rnd.next(1, n);
        int missing_pos = -1;
        for (int i = 0; i < n; ++i) {
            if (perm[i] == missing_num) {
                missing_pos = i;
                break;
            }
        }
        int dup_pos;
        do {
            dup_pos = rnd.next(0, n - 1);
        } while (dup_pos == missing_pos);
        perm[missing_pos] = perm[dup_pos];
        a = perm;
    } else {
        // Default to random
        for (int i = 0; i < n; ++i) {
            a[i] = rnd.next(1, n);
        }
    }

    // Output n
    printf("%d\n", n);
    // Output array a
    for (int i = 0; i < n; ++i) {
        printf("%d", a[i]);
        if (i < n - 1) printf(" ");
    }
    printf("\n");

    return 0;
}

