        } else if (type == "edge") {
            // Generate edge case messages
            if (i % 4 == 0) {
                // Empty message (should output NA)
                message = "";
            } else if (i % 4 == 1) {
                // Maximum length message with spaces
                len = maxlen / 2;
                for (int j = 0; j < len; ++j) {
