#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

bool point_on_segment(int x1, int y1, int x2, int y2, int x, int y) {
    // Check if (x,y) is colinear with (x1,y1)-(x2,y2)
    int cross = (x - x1)*(y2 - y1) - (y - y1)*(x2 - x1);
    if (cross != 0) return false; // Not colinear

    // Now check if (x,y) lies between (x1,y1)-(x2,y2)
    int dot = (x - x1)*(x2 - x1) + (y - y1)*(y2 - y1);
    if (dot < 0) return false; // Not between
    int len_sq = (x2 - x1)*(x2 - x1) + (y2 - y1)*(y2 - y1);
    if (dot > len_sq) return false; // Not between

    return true;
}

int main(int argc, char* argv[]) {
    registerValidation(argc, argv);
    int n = inf.readInt(1, 10000, "n");
    inf.readEoln();

    for (int i = 0; i < n; ++i) {
        // Read the 10 integers
        int xp1 = inf.readInt(-1000, 1000, "xp1");
        inf.readSpace();
        int yp1 = inf.readInt(-1000, 1000, "yp1");
        inf.readSpace();
        int xp2 = inf.readInt(-1000, 1000, "xp2");
        inf.readSpace();
        int yp2 = inf.readInt(-1000, 1000, "yp2");
        inf.readSpace();
        int xp3 = inf.readInt(-1000, 1000, "xp3");
        inf.readSpace();
        int yp3 = inf.readInt(-1000, 1000, "yp3");
        inf.readSpace();
        int xk = inf.readInt(-1000, 1000, "xk");
        inf.readSpace();
        int yk = inf.readInt(-1000, 1000, "yk");
        inf.readSpace();
        int xs = inf.readInt(-1000, 1000, "xs");
        inf.readSpace();
        int ys = inf.readInt(-1000, 1000, "ys");
        inf.readEoln();

        // Check triangle is valid (non-degenerate)
        int area2 = (xp2 - xp1)*(yp3 - yp1) - (xp3 - xp1)*(yp2 - yp1);
        ensuref(area2 != 0, "The triangle formed by the vertices is degenerate at query %d", i+1);

        // Check that cow and weaver are not on the apex of the triangle
        for (pair<int,int> p : {make_pair(xk, yk), make_pair(xs, ys)}) {
            int x = p.first;
            int y = p.second;
            ensuref(!(x == xp1 && y == yp1), "Point (%d,%d) lies on vertex of triangle at query %d", x, y, i+1);
            ensuref(!(x == xp2 && y == yp2), "Point (%d,%d) lies on vertex of triangle at query %d", x, y, i+1);
            ensuref(!(x == xp3 && y == yp3), "Point (%d,%d) lies on vertex of triangle at query %d", x, y, i+1);
        }

        // Check that cow and weaver are not on the sides of the triangle
        for (pair<int,int> p : {make_pair(xk, yk), make_pair(xs, ys)}) {
            int x = p.first;
            int y = p.second;
            bool on_side = false;

            // Edge1: (xp1, yp1)-(xp2, yp2)
            if (point_on_segment(xp1, yp1, xp2, yp2, x, y)) on_side = true;
            // Edge2: (xp2, yp2)-(xp3, yp3)
            if (point_on_segment(xp2, yp2, xp3, yp3, x, y)) on_side = true;
            // Edge3: (xp3, yp3)-(xp1, yp1)
            if (point_on_segment(xp3, yp3, xp1, yp1, x, y)) on_side = true;

            ensuref(!on_side, "Point (%d,%d) lies on side of triangle at query %d", x, y, i+1);
        }
    }

    inf.readEof();
    return 0;
}

