void generate_chain(int n, int minL, int maxL, vector<tuple<int,int,int>>& edges) {
    for(int i = 1; i < n; ++i) {
        int u = i;
        int v = i + 1;
        int l = rnd.next(minL, maxL);
        edges.push_back({u, v, l});
    }
}

void generate_star(int n, int minL, int maxL, vector<tuple<int,int,int>>& edges) {
    for(int i = 2; i <= n; ++i) {
        int u = 1;
        int v = i;
        int l = rnd.next(minL, maxL);
        edges.push_back({u, v, l});
    }
}

void generate_random_tree(int n, int minL, int maxL, vector<tuple<int,int,int>>& edges) {
    vector<int> nodes(n);
    for(int i = 0; i < n; ++i) nodes[i] = i+1;
    shuffle(nodes.begin(), nodes.end());
    for(int i = 1; i < n; ++i) {
        int u = nodes[i];
        int v = nodes[rnd.next(0, i-1)];
        int l = rnd.next(minL, maxL);
        edges.push_back({u, v, l});
    }
}

void generate_random_connected_graph(int n, int m, int minL, int maxL, vector<tuple<int,int,int>>& edges) {
    vector<int> parent(n+1);
    for (int i = 1; i <= n; ++i) parent[i] = i;

    function<int(int)> find = [&](int u) {
        return parent[u] == u ? u : parent[u] = find(parent[u]);
    };

    map< pair<int,int>, int > edge_counts;

    int edge_added = 0;
    while(edge_added < n - 1) {
        int u = rnd.next(1, n);
        int v = rnd.next(1, n);
        if(u == v) continue;
        int pu = find(u);
        int pv = find(v);
        if (pu != pv) {
            parent[pu] = pv;
            int a = min(u,v);
            int b = max(u,v);
            edge_counts[{a,b}]++;
            int l = rnd.next(minL, maxL);
            edges.push_back({u, v, l});
            ++edge_added;
        } 
    }

    // Now add extra edges
    int need = m - (n - 1);
    while(need > 0) {
        int u = rnd.next(1,n);
        int v = rnd.next(1,n);
        if(u == v) continue;
        int a = min(u,v);
        int b = max(u,v);
        int cnt = edge_counts[{a,b}];
        if(cnt >=2) continue; // have two edges already
        int l = rnd.next(minL, maxL);
        edges.push_back({u, v, l});
        edge_counts[{a,b}]++;
        --need;
    }
    // shuffle edges
    shuffle(edges.begin(), edges.end());
}

