        int t;
        int pos;
        int id;
        double res;
        Query(int id, int pos, int t) {
            this.id = id;
            this.t = t;
            this.pos = pos;
        }

        @Override
        public int compareTo(Query o) {
            return t - o.t;
        }
    }

    static class IN {
        double lh;
        double rh;
        double water;
        int lpos;
        int rpos;
        IN(double lh, double rh, double water, int lpos, int rpos) {
            this.lh = lh;
            this.rh = rh;
            this.water = water;
            this.lpos = lpos;
            this.rpos = rpos;
        }
    }

    // Comparator as static field
    private static final Comparator<Query> COMP = new Comparator<Query>() {
        @Override
        public int compare(Query o1, Query o2) {
            return o1.id - o2.id;
        }
    };

    // Static helper methods
    public static int upperBound(int[] a, int val) {
        int f = 0;
        int l = a.length;
        int len = l - f;
        while (len > 0) {
            int half = len >> 1;
            int mid = f + half;
            if (val < a[mid]) {
                len = half;
            } else {
                f = mid;
                ++f;
                len = len - half - 1;
            }
        }
        return f;
    }

    public static int lowerBound(int[] a, int val) {
        int f = 0;
        int l = a.length;
        int len = l - f;
        while (len > 0) {
            int half = len >> 1;
            int mid = f + half;
            if (a[mid] < val) {
                f = mid;
                ++f;
                len = len - half - 1;
            } else {
                len = half;
            }
        }
        return f;
    }

    // Output methods
    static String str(Boolean o) {
        return o ? "YES" : "NO";
    }

    static <K, V> String str(Map<K, V> map) {
        StringBuilder sb = new StringBuilder();
        boolean isFirst = true;
        for (Entry<K, V> set : map.entrySet()) {
            if (!isFirst) {
                sb.append(BR);
            }
            sb.append(str(set.getKey())).append(':').append(str(set.getValue()));
            isFirst = false;
        }
        return sb.toString();
    }

    static <E> String str(Collection<E> list) {
        StringBuilder sb = new StringBuilder();
        boolean isFirst = true;
        for (E e : list) {
            if (!isFirst) {
                sb.append(' ');
            }
            sb.append(str(e));
            isFirst = false;
        }
        return sb.toString();
    }

