        if (c.equals(Boolean.class)) {
            return str((Boolean) o);
        }
        return o.toString();
    }

    static int getArrayDepth(Object o) {
        if (!o.getClass().isArray() || Array.getLength(o) == 0) {
            return 0;
        }
        return 1 + getArrayDepth(Array.get(o, 0));
    }

