                                            p.rh = nxt.rh;
                                            ins.remove(nxt);
                                        }
                                    }
                                    changed = true;
                                    break;
                                }
                            }
                        }
                        if (!changed) {
                            break;
                        }
                    }
                }
                int pos = -1;
                for (int k = 0; k < ins.size(); k++) {
                    if (ins.get(k).lpos < qs[i].pos && qs[i].pos < ins.get(k).rpos) {
