using namespace std;

const int MIN_WH = 4;
const int MAX_WH = 100;
const int MAX_N = 100;

int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);
    int W = opt<int>("W", 10); // Default W = 10
    int H = opt<int>("H", 10); // Default H = 10
    int N = opt<int>("N", 10); // Default N = 10
    string type = opt<string>("type", "random");

    // Ensure W, H are within constraints
    W = max(MIN_WH, min(MAX_WH, W));
    H = max(MIN_WH, min(MAX_WH, H));
    N = max(0, min(MAX_N, N));

    vector<int> pi;

    if (type == "n0") {
        N = 0;
        pi.clear();
    } else if (type == "maxN") {
        N = MAX_N;
        pi.resize(N);
    } else {
        pi.resize(N);
    }

    if (type == "all0") {
        fill(pi.begin(), pi.end(), 0);
    } else if (type == "all1") {
        fill(pi.begin(), pi.end(), 1);
    } else if (type == "alternating") {
        for (int i = 0; i < N; ++i) {
            pi[i] = i % 2;
        }
    } else if (type == "random") {
        for (int i = 0; i < N; ++i) {
            pi[i] = rnd.next(0, 1);
        }
    } else if (type == "pattern1") {
        for (int i = 0; i < N; ++i) {
            if (i % 3 == 0) pi[i] = 0;
            else pi[i] = 1;
        }
    } else if (type == "pattern2") {
        for (int i = 0; i < N; ++i) {
            if (i < N / 2) pi[i] = 0;
            else pi[i] = 1;
        }
    } else if (type == "pattern3") {
        for (int i = 0; i < N; ++i) {
            if (i < N / 2) pi[i] = 1;
            else pi[i] = 0;
        }
    } else {
        // Default to random
        for (int i = 0; i < N; ++i) {
            pi[i] = rnd.next(0, 1);
        }
    }

    // Output W H
    printf("%d %d\n", W, H);
    // Output N
    printf("%d\n", N);
    // Output pi
    for (int i = 0; i < N; ++i) {
        printf("%d", pi[i]);
        if (i + 1 < N) printf(" ");
    }
    if (N > 0) printf("\n");
    return 0;
}

