#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    int nt = opt<int>("nt", 1);       // number of test datasets
    int h = opt<int>("h", 1);         // height
    int w = opt<int>("w", 1);         // width
    string type = opt<string>("type", "safe");  // type of test case: 'safe' or 'suspicious'

    printf("%d\n", nt);

    for (int dataset = 0; dataset < nt; ++dataset) {
        // For each dataset, generate H, W, and the grid
        int H = h;
        int W = w;

        printf("%d %d\n", H, W);

        vector<string> grid(H);

        if (type == "safe") {
            // Generate a grid where all materials form rectangles

            // Decide the number of materials (up to 7)
            int num_materials = rnd.next(1, 7);

            // Generate rectangles for each material
            vector<char> materials;
            for(int i = 0; i < num_materials; ++i) {
                materials.push_back('A' + i);
            }

            // For each material, generate a rectangle
            vector<vector<int>> rectangles;

            for(int m = 0; m < num_materials; ++m) {
                // Randomly choose the rectangle parameters
                int min_h = H / 5;
                int min_w = W / 5;
                min_h = max(1, min_h);
                min_w = max(1, min_w);
                int rect_h = rnd.next(min_h, H);
                int rect_w = rnd.next(min_w, W);

                int y = rnd.next(0, H - rect_h);
                int x = rnd.next(0, W - rect_w);

                rectangles.push_back({y, x, y + rect_h - 1, x + rect_w -1, m});
            }

            // Now, simulate overlapping by assigning x-coordinates (depth) to materials
            vector<int> x_coords(num_materials);
            set<int> used_x;
            for(int m = 0; m < num_materials; ++m) {
                int xc;
                do {
                    xc = rnd.next(1, 1000);  // Arbitrary range
                } while (used_x.count(xc));
                used_x.insert(xc);
                x_coords[m] = xc;
            }

            // Now, sort materials by x_coords so that overlapping works
            vector<int> order(num_materials);
            for(int m = 0; m < num_materials; ++m) order[m] = m;
            sort(order.begin(), order.end(), [&](int a, int b){
                return x_coords[a] < x_coords[b];
            });

            // Initialize grid with '.'
            for(int i = 0; i < H; ++i) grid[i] = string(W, '.');

            // For each material in x_coords order, from back to front
            for(int idx = 0; idx < num_materials; ++idx) {
                int m = order[idx];
                char mat = materials[m];
                auto rect = rectangles[m];
                int y1 = rect[0];
                int x1 = rect[1];
                int y2 = rect[2];
                int x2 = rect[3];

                for(int y = y1; y <= y2; ++y){
                    for(int x = x1; x <= x2; ++x){
                        grid[y][x] = mat;
                    }
                }
            }

            // Output grid
            for(int i = 0; i < H; ++i){
                printf("%s\n", grid[i].c_str());
            }

        } else if (type == "suspicious") {
            // Generate a grid where at least one material does not form a rectangle

            // First generate 'safe' materials
            int num_materials = rnd.next(1, 7);
            int num_suspicious = rnd.next(1, num_materials);

            vector<char> materials;
            for(int i = 0; i < num_materials; ++i) {
                materials.push_back('A' + i);
            }

            vector<vector<int>> rectangles;

            for(int m = 0; m < num_materials - num_suspicious; ++m) {
                // Randomly choose the rectangle parameters
                int min_h = H / 5;
                int min_w = W / 5;
                min_h = max(1, min_h);
                min_w = max(1, min_w);
                int rect_h = rnd.next(min_h, H);
                int rect_w = rnd.next(min_w, W);

                int y = rnd.next(0, H - rect_h);
                int x = rnd.next(0, W - rect_w);

                rectangles.push_back({y, x, y + rect_h - 1, x + rect_w -1, m});
            }

            // For suspicious materials, create shapes that are not rectangles
            vector<vector<pair<int, int>>> suspicious_shapes;

            for(int m = num_materials - num_suspicious; m < num_materials; ++m) {
                vector<pair<int, int>> cells;

                // Create an L-shaped figure
                int min_h = H / 5;
                int min_w = W / 5;
                min_h = max(1, min_h);
                min_w = max(1, min_w);
                int rect_h = rnd.next(min_h, H);
                int rect_w = rnd.next(min_w, W);

                int y = rnd.next(0, H - rect_h);
                int x = rnd.next(0, W - rect_w);

                // Vertical part of 'L'
                for(int dy = 0; dy < rect_h; ++dy){
                    cells.push_back({y + dy, x});
                }
                // Horizontal part of 'L'
                for(int dx = 1; dx < rect_w; ++dx){
                    cells.push_back({y + rect_h -1, x + dx});
                }
                suspicious_shapes.push_back(cells);
            }

            // Now, simulate overlapping by assigning x-coordinates (depth) to materials
            vector<int> x_coords(num_materials);
            set<int> used_x;
            for(int m = 0; m < num_materials; ++m) {
                int xc;
                do {
                    xc = rnd.next(1, 1000);  // Arbitrary range
                } while (used_x.count(xc));
                used_x.insert(xc);
                x_coords[m] = xc;
            }

            // Now, sort materials by x_coords so that overlapping works
            vector<int> order(num_materials);
            for(int m = 0; m < num_materials; ++m) order[m] = m;
            sort(order.begin(), order.end(), [&](int a, int b){
                return x_coords[a] < x_coords[b];
            });

            // Initialize grid with '.'
            for(int i = 0; i < H; ++i) grid[i] = string(W, '.');

            // For each material in x_coords order, from back to front
            for(int idx = 0; idx < num_materials; ++idx) {
                int m = order[idx];
                char mat = materials[m];
                if (m < num_materials - num_suspicious) {
                    auto rect = rectangles[m];
                    int y1 = rect[0];
                    int x1 = rect[1];
                    int y2 = rect[2];
                    int x2 = rect[3];

                    for(int y = y1; y <= y2; ++y){
                        for(int x = x1; x <= x2; ++x){
                            grid[y][x] = mat;
                        }
                    }
                } else {
                    auto cells = suspicious_shapes[m - (num_materials - num_suspicious)];
                    for(auto cell : cells){
                        int y = cell.first;
                        int x = cell.second;
                        grid[y][x] = mat;
                    }
                }
            }

            // Output grid
            for(int i = 0; i < H; ++i){
                printf("%s\n", grid[i].c_str());
            }

        } else if (type == "random") {
            // Generate a random grid with random letters
            for(int i = 0; i < H; ++i) {
                string line = "";
                for(int j = 0; j < W; ++j){
                    int coin = rnd.next(3);
                    if (coin == 0){
                        line += '.';
                    } else {
                        char c = 'A' + rnd.next(0, 6); // Up to 7 materials
                        line += c;
                    }
                }
                grid[i] = line;
            }

            // Output grid
            for(int i = 0; i < H; ++i){
                printf("%s\n", grid[i].c_str());
            }

        } else {
            // Unknown type
            fprintf(stderr, "Unknown type: %s\n", type.c_str());
            exit(1);
        }
    }

    return 0;
}

