using namespace std;

int main(int argc, char* argv[]) {
    registerValidation(argc, argv);
    int N = inf.readInt(1, 100, "N");
    inf.readEoln();

    long long totalHW = 0;

    for (int dataSetNo = 0; dataSetNo < N; dataSetNo++) {
        int H = inf.readInt(1, 50, "H");
        inf.readSpace();
        int W = inf.readInt(1, 50, "W");
        inf.readEoln();

        totalHW += H * W;

        set<char> materials;  // Collect materials used in this dataset

        for (int i = 0; i < H; i++) {
            string line = inf.readLine();
            ensuref((int)line.length() == W, "Line %d length is %d, expected %d", i+1, (int)line.length(), W);

            for (char c : line) {
                ensuref(c == '.' || (c >= 'A' && c <= 'Z'), "Invalid character '%c' at line %d", c, i+1);
                if (c != '.')
                    materials.insert(c);
            }
        }
        ensuref(materials.size() <= 7, "Too many material types in dataset %d: %d > 7", dataSetNo+1, (int)materials.size());
    }

    ensuref(totalHW <= 1000000, "Total size of data exceeds 1,000,000");
    inf.readEof();
    return 0;
}

