            for (char c = 'A'; c <= 'Z'; c++) {
                size[c] = new Size(100, 0, 100, 0);
            }
            array.clear();
        }

        private boolean alf(char c) {
            for (int i = size[c].miny; i < size[c].maxy; i++) {
                for (int j = size[c].minx; j < size[c].maxx; j++) {
                    if (map[i][j] == '.') {
                        return false;
                    }
                }
            }
            return true;
        }

        private boolean alfCheck(char c) {
            for (int i = size[c].miny; i < size[c].maxy; i++) {
                for (int j = size[c].minx; j < size[c].maxx; j++) {
                    if (map[i][j] != c) {
                        if (map[i][j] != '1') {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        private void same(char c) {
            for (int i = size[c].miny; i < size[c].maxy; i++) {
                for (int j = size[c].minx; j < size[c].maxx; j++) {
                    map[i][j] = '1';
                }
            }
        }

        private String check() {
            for (char c = 'A'; c <= 'Z'; c++) {
                if (size[c].maxx - size[c].minx < 0 || size[c].maxy - size[c].miny < 0) {
