                for (int i = 0; i < array.size(); i++) {
                    if (alfCheck(array.get(i))) {
                        same(array.get(i));
                        array.remove(i);
                        break;
                    }
                }
                if (cnt == array.size()) {
                    return "SUSPICIOUS";
                }
                cnt = array.size();
            }
            return "SAFE";
        }

        private void doIt() {
            int n = sc.nextInt();
            for (int i = 0; i < n; i++) {
                int h = sc.nextInt();
                int w = sc.nextInt();
