        return 1;
    }

    string S;

    if (type == "random") {
        // Random string of length n with '0's and '1's.
        for (int i = 0; i < n; ++i) {
            S += rnd.next(0, 1) ? '1' : '0';
        }
    } else if (type == "all_zero") {
        S = string(n, '0');
    } else if (type == "all_one") {
        S = string(n, '1');
    } else if (type == "alternate") {
        for (int i = 0; i < n; ++i) {
            S += (i % 2 == 0) ? '0' : '1';
        }
    } else if (type == "half_half") {
        // First half '0's, second half '1's
        S = string(n / 2, '0') + string(n - n / 2, '1');
    } else if (type == "one_zero_one") {
        // '1's at the start and end, '0's in the middle
        if (n >= 2) {
            S = "1" + string(n - 2, '0') + "1";
        } else if (n == 1) {
            S = "1";
        } else {
            S = ""; // n == 0, should not happen due to earlier check
        }
    } else if (type == "long_zero_one") {
        // Starting with long sequence of '0's followed by '1's
        if (n >= 2) {
            int k = rnd.next(1, n - 1); // number of zeros
            S = string(k, '0') + string(n - k, '1');
        } else {
            S = string(n, '0'); // if n == 1
        }
    } else if (type == "random_sparse_ones") {
        // Random string with few '1's at random positions
        S = string(n, '0');
        int ones = rnd.next(1, min(n, 10)); // up to 10 ones
        set<int> positions;
        while (positions.size() < ones) {
            positions.insert(rnd.next(0, n - 1));
        }
        for (int pos : positions) {
            S[pos] = '1';
        }
    } else if (type == "random_sparse_zeros") {
        // Random string with few '0's at random positions
        S = string(n, '1');
        int zeros = rnd.next(1, min(n, 10)); // up to 10 zeros
        set<int> positions;
        while (positions.size() < zeros) {
            positions.insert(rnd.next(0, n - 1));
        }
        for (int pos : positions) {
            S[pos] = '0';
        }
    } else {
        // Default random string
        for (int i = 0; i < n; ++i) {
            S += rnd.next(0, 1) ? '1' : '0';
        }
    }

    cout << S << endl;

    return 0;
}

