inline int read()
{
	int x=0; bool f=1; char c=getchar();
	for(;!isdigit(c);c=getchar()) if(c=='-') f=0;
	for(; isdigit(c);c=getchar()) x=(x<<3)+(x<<1)+(c^'0');
	if(f) return x;
	return -x;
}

const int N = 500;
llong a[N+3][N+3];
llong s[2][N+3][N+3];
llong dp[N+3][N+3];
int n;

void update(llong &x,llong y) {x = x<y?x:y;}

llong getsum(int typ,int lx,int rx,int ly,int ry)
{
	return s[typ][rx][ry]-s[typ][lx-1][ry]-s[typ][rx][ly-1]+s[typ][lx-1][ly-1];
}

int main()
{
	scanf("%d",&n);
	for(int i=1; i<=n; i++)
	{
		for(int j=1; j<=n; j++)
		{
			if(j==i) continue;
			scanf("%lld",&a[i][j]);
		}
	}
	for(int i=1; i<=n; i++)
	{
		for(int j=1; j<=n; j++)
		{
			if(i<j) {s[0][i][j] = a[i][j];}
			s[0][i][j] += s[0][i][j-1];
		}
		for(int j=1; j<=n; j++) s[0][i][j] += s[0][i-1][j];
	}
	for(int i=1; i<=n; i++)
	{
		for(int j=1; j<=n; j++)
		{
			if(i>j) {s[1][i][j] = a[i][j];}
			s[1][i][j] += s[1][i][j-1];
		}
		for(int j=1; j<=n; j++) s[1][i][j] += s[1][i-1][j];
	}
	memset(dp,42,sizeof(dp)); 
	dp[0][0] = 0ll;
	for(int i=0; i<=n; i++)
	{
		for(int j=0; j<max(i,1); j++)
		{
//			printf("dp[%d][%d]=%lld\n",i,j,dp[i][j]);
			for(int k=i+1; k<=n; k++)
			{
				llong tmp = dp[i][j]+getsum(1,k+1,n,j+1,i)+getsum(0,i+1,k,i+1,k);
				update(dp[k][i],tmp);
//				printf("update dp[%d][%d]=%lld\n",k,i,tmp);
			}
		}
	}
	llong ans = dp[n][1];
	for(int i=1; i<=n; i++) update(ans,dp[n][i]);
	printf("%lld\n",ans);
	return 0;
}

