    registerTestlibCmd(argc, argv);

    string s = inf.readLine();
    string t = inf.readLine();

    int n = s.size();
    int m = t.size();

    // Compute the length of the longest common subsequence (LCS)
    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            if (s[i - 1] == t[j - 1])
                dp[i][j] = dp[i - 1][j - 1] + 1;
            else
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
        }
    }
    int maxlen = dp[n][m];

    // Read participant's output
    string ans = ouf.readLine();

    // Check that ans only contains lowercase letters
    if (!ans.empty()) {
        for (char c : ans) {
            if (c < 'a' || c > 'z') {
                quitf(_wa, "Your output contains invalid characters.");
            }
        }
    }

    // Check that ans is a subsequence of s
    if (!isSubsequence(ans, s)) {
        quitf(_wa, "Your output is not a subsequence of the first string.");
    }

    // Check that ans is a subsequence of t
    if (!isSubsequence(ans, t)) {
        quitf(_wa, "Your output is not a subsequence of the second string.");
    }

    // Check that the length of ans is equal to the length of the LCS
    if ((int)ans.size() != maxlen) {
        quitf(_wa, "Your LCS length is %d, but the maximum possible length is %d.", (int)ans.size(), maxlen);
    }

    quitf(_ok, "Correct. Length = %d", maxlen);
