int N, Y;

bool solutionExists() {
    // Try to find x, y, z such that:
    // x + y + z = N
    // 10000x + 5000y + 1000z = Y
    // x, y, z >= 0 and integers
    for (int x = 0; x <= N; x++) {
        int remaining_bills = N - x;
        int remaining_amount = Y - 10000 * x;
        if (remaining_amount < 0) continue;
        for (int y = 0; y <= remaining_bills; y++) {
            int z = remaining_bills - y;
            int total = 10000 * x + 5000 * y + 1000 * z;
            if (total == Y) {
                return true;
            }
        }
    }
    return false;
}

int main(int argc, char* argv[]) {
    registerTestlibCmd(argc, argv);
    N = inf.readInt(1, 2000, "N");
    Y = inf.readInt(1000, 20000000, "Y");

    int x = ouf.readInt(-1, N, "x");
    int y = ouf.readInt(-1, N, "y");
    int z = ouf.readInt(-1, N, "z");

    if (x == -1 && y == -1 && z == -1) {
        if (solutionExists()) {
            quitf(_wa, "Contestant claims impossible when a solution exists");
        } else {
            // Correct, impossible
            quitf(_ok, "Correct, impossible");
        }
    } else {
        if (x < 0 || y < 0 || z < 0) {
            quitf(_wa, "x, y, z must be non-negative integers");
        }
        if (x + y + z != N) {
            quitf(_wa, "x + y + z != N");
        }
        if (10000LL * x + 5000LL * y + 1000LL * z != Y) {
            quitf(_wa, "Total amount doesn't equal Y");
        }
        // All checks passed
        quitf(_ok, "Correct");
    }
}

