        A = A_given;
        B = B_given;
        C = C_given;
        D = D_given;
    } else if (type == "min") {
        N = N_MIN;
        A = B = C = D = 1;
    } else if (type == "max") {
        N = N_MAX;
        A = 1;
        B = N;
        C = 1;
        D = N;
    } else if (type == "random") {
        N = rnd.next(N_MIN, N_MAX);
        A = rnd.next(1, N);
        B = rnd.next(A, N);
        C = rnd.next(1, N);
        D = rnd.next(C, N);
    } else if (type == "no_solution") {
        // Generate N, A, B, C, D where there is no grouping possible.
        int tries = 0;
        while (tries++ < 100) {
            N = rnd.next(N_MIN, N_MAX);
            A = rnd.next(1, N);
            B = rnd.next(A, N);
            bool divisible = false;
            for (int k = A; k <= B; k++) {
                if (N % k == 0) {
                    divisible = true;
                    break;
                }
            }
            if (!divisible) break;
        }
        if (tries >= 100) {
            N = N_MAX;
            A = N - 1;
            B = N - 1;
        }
        C = rnd.next(1, N);
        D = rnd.next(C, N);
    } else if (type == "boundary") {
        int boundary_type = rnd.next(1, 4);
        switch(boundary_type) {
            case 1:
                N = N_MIN;
                break;
            case 2:
                N = N_MIN + 1;
                break;
            case 3:
                N = N_MAX - 1;
                break;
            case 4:
                N = N_MAX;
                break;
        }
        A = rnd.next(1, N);
        B = rnd.next(A, N);
        C = rnd.next(1, N);
        D = rnd.next(C, N);
