        A = B = rnd.next(1, N);
        C = rnd.next(1, N);
        D = rnd.next(C, N);
    } else if (type == "large_numbers") {
        N = N_MAX;
        A = rnd.next(1, N);
        B = N;
        C = rnd.next(1, N);
